def _style_chiffres(style):
    """Retourne (police, gris) des chiffres selon la gamme choisie."""
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO


# ══ LA MAQUETTE DE RANIHEI ═══════════════════════════════════════════
# Dimensions du carton relevé sur le cadre de sa planche de 6. Tout le
# reste est en MILLIÈMES de ces deux nombres : le carton peut grandir ou
# rétrécir, le dessin ne se déforme jamais.
MAQ_W, MAQ_H = 747.0, 325.0

# Les sept tranches du tirage, dans l'ordre des bulles (gauche -> droite).
TRANCHES = [(1, 13), (14, 26), (27, 39), (40, 52), (53, 65), (66, 78), (79, 90)]

# Les sept bulles : x, y, rayon — en millièmes, relevés sur SON dessin.
# ⚠️ Chaque centre a été choisi ainsi : on mesure la distance de chaque
#    point blanc au trait le plus proche, on garde ceux qui conservent au
#    moins 88 % du dégagement maximal, et parmi eux le plus proche du
#    centre visuel. Le chiffre est donc centré à l'œil ET ne touche
#    jamais un trait de RANIHEI.
# ⚠️ L'ORDRE EST CELUI DE LA LECTURE : de gauche à droite.
