_T_BULLE = 32.0
# ⚠️⚠️ 32 pt EST LE MAXIMUM, ET IL A ÉTÉ MESURÉ, PAS CALCULÉ.
#    On a imprimé à 500 dpi CHAQUE valeur de CHAQUE tranche, dans SA
#    bulle, avec le gras du contour, et compté les pixels où le chiffre
#    touche un trait de RANIHEI :
#       32 pt → aucun contact
#       33 pt → 8 pixels sur le « 84 » de la 7e bulle (la plus petite)
#       34 pt → 100 px repartis sur six bulles   35 pt → 389   36 pt → 933
#    ⚠️ NE PAS MONTER SANS REFAIRE CETTE MESURE.
_GARDE = 1.05
# ⚠️⚠️ CE FACTEUR N'EST PAS UNE MARGE, C'EST UN ÉTALONNAGE : réglé pour
#    laisser passer exactement les 32 pt validés sur le carton
#    d'aujourd'hui, et pas un point de plus. Si le carton rapetisse un
#    jour, le garde-fou fera redescendre les chiffres tout seul.

# Le retrait du cadre de microtexte. MESURÉ sur sept valeurs :
#    0,4 mm -> 395 px   0,8 -> 15   1,0 -> 21   1,2 -> 30
#    1,6 mm -> 53       2,0 -> 113  3,0 -> 155
# 0,8 mm serait un peu plus propre, mais colle au trait de coupe : un
# massicot de travers emporterait le microtexte, donc la protection
# anti-photocopie. 1,2 mm est le retrait de AHE, BLOSSOM PEARL, MAKEMO
# et TUREIA, et 30 pixels a 500 dpi (un pixel = 0,05 mm) ne se voient pas.
_RETRAIT = 1.2 * mm

# La pastille « Série : » : à la place EXACTE des « 001 » effacés.
#   SERIE_GAUCHE : le bord gauche des chiffres, juste après les deux points
#   SERIE_BASE   : leur ligne de pied
#   SERIE_PT     : leur hauteur d'origine convertie en corps de police
#   SERIE_LARG   : la place libre jusqu'au cadre arrondi, en fraction de
#                  la largeur du carton — six chiffres au lieu de trois.
SERIE_GAUCHE = 923.7
SERIE_BASE = 126.2
SERIE_PT = 81.2
SERIE_LARG = 0.057


